stage_a_raw:
{
  "decisions": [
    {
      "decision": "domain_of_flow_variables",
      "evidence": "Demand of Each Retail Store (in units) ... Supply Capacity of Each Distribution Center (in units)",
      "options": [
        "NonNegativeReals",
        "NonNegativeIntegers"
      ],
      "plausibility": [
        0.6,
        0.4
      ],
      "majority_option": "NonNegativeReals"
    },
    {
      "decision": "open_limit_direction",
      "evidence": "\"considering the feasibility of opening up to eight different distribution centers\"",
      "options": [
        "sum(y) <= 8",
        "sum(y) <= 7",
        "sum(y) = 8"
      ],
      "plausibility": [
        0.85,
        0.1,
        0.05
      ],
      "majority_option": "sum(y) <= 8"
    },
    {
      "decision": "demand_constraint_direction",
      "evidence": "\"determining the optimal shipping routes to fulfill the demands of all retail stores\"",
      "options": [
        "sum_i x[i,j] == demand[j]",
        "sum_i x[i,j] >= demand[j]"
      ],
      "plausibility": [
        0.9,
        0.1
      ],
      "majority_option": "sum_i x[i,j] == demand[j]"
    },
    {
      "decision": "capacity_link_form",
      "evidence": "\"Each distribution center has a unique set of operational costs and capacities\"",
      "options": [
        "sum_j x[i,j] <= capacity[i] * y[i]",
        "sum_j x[i,j] <= capacity[i]"
      ],
      "plausibility": [
        0.95,
        0.05
      ],
      "majority_option": "sum_j x[i,j] <= capacity[i] * y[i]"
    },
    {
      "decision": "objective_units_scale",
      "evidence": "\"Opening Costs for Each Distribution Center (in dollars)\" and \"Transportation Cost Per Unit ... (in dollars)\"",
      "options": [
        "dollars (opening cost + per-unit transport cost * units)",
        "thousands of dollars (divide all costs by 1000)"
      ],
      "plausibility": [
        0.95,
        0.05
      ],
      "majority_option": "dollars (opening cost + per-unit transport cost * units)"
    },
    {
      "decision": "transport_cost_orientation",
      "evidence": "\"Transportation Cost Per Unit from Each Distribution Center to Retail Stores\"",
      "options": [
        "rows = distribution centers, columns = retail stores (cost[i][j])",
        "rows = retail stores, columns = distribution centers (cost[j][i])"
      ],
      "plausibility": [
        0.97,
        0.03
      ],
      "majority_option": "rows = distribution centers, columns = retail stores (cost[i][j])"
    }
  ]
}
